<template>
  <section class="panel" aria-labelledby="adjust-title">
    <h2 id="adjust-title">履约、暂留与退款核对</h2>
    <p class="hint">所有调整追加新记录，不修改历史分配。部分退款先记录实际退款，再逐项核对，不默认把所有工作等比例扣回。</p>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="message" role="status" class="notice">{{ message }}</p>
    <form @submit.prevent="recordDelivery"><fieldset :disabled="busy" style="border:0;padding:0"><h3>内部交付职责</h3><div class="fields"><label>订单<select v-model.number="delivery.order_id" required @change="loadDeliveries"><option :value="0" disabled>选择订单</option><option v-for="order in orders" :key="order.id" :value="order.id">#{{ order.id }} {{ order.commercial.definition.name }}</option></select></label><label>职责<select v-model="delivery.service_code" required><option value="" disabled>选择职责</option><option v-for="service in serviceCodes" :key="service.code" :value="service.code">{{ service.label }}</option></select></label><label>凭证编号<input v-model="delivery.evidence" required></label><label>完成说明<input v-model="delivery.note" required></label></div><div class="actions"><button>记录已完成职责</button></div><p class="hint">此处不能替代客户已购买服务的履约次数；套餐服务需在“商品与项目权益”中逐次确认。</p></fieldset></form>
    <form @submit.prevent="postRefund"><fieldset :disabled="busy" style="border:0;padding:0"><h3>登记实际退款</h3><div class="fields"><label>订单<select v-model.number="refund.order_id" required @change="refund.idempotency_key = cryptoId()"><option :value="0" disabled>选择订单</option><option v-for="order in orders.filter(o => o.status === 'paid')" :key="order.id" :value="order.id">#{{ order.id }} · 实收 {{ order.amount }} · 已退 {{ order.refund_amount }}</option></select></label><label>本次实际退款额<input v-model="refund.amount" inputmode="decimal" required></label><label>退款原因<input v-model="refund.reason" required></label><label>退款凭据<input v-model="refund.evidence" required></label></div><div class="actions"><button>确认登记退款</button></div></fieldset></form>
    <div class="table-wrap"><table><thead><tr><th>退款核对</th><th>累计退款</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in reviews" :key="item.id"><td>订单 #{{ item.order_id }} · {{ item.reason }}</td><td>{{ item.refunded_total }}</td><td>{{ item.status === 'pending' ? '待核对' : '已核对' }}</td><td><button :disabled="busy || item.status !== 'pending'" @click="openReview(item)">逐项核对</button></td></tr></tbody></table></div>
    <form v-if="review" @submit.prevent="resolveReview"><fieldset :disabled="busy" style="border:0;padding:0"><h3>订单 #{{ review.order_id }} 的分配调整</h3><p class="hint">仅填写受影响项目的扣减金额；已付历史仍保留，可能形成待收回余额。</p><div class="table-wrap"><table><thead><tr><th>明细</th><th>可调整余额</th><th>本次扣减</th></tr></thead><tbody><tr v-for="item in reductions" :key="item.entry_id"><td>#{{ item.entry_id }} {{ item.label }}</td><td>{{ item.expected_remaining }}</td><td><input v-model="item.amount" inputmode="decimal" aria-label="本次扣减金额" placeholder="不受影响则留空"></td></tr></tbody></table></div><div class="fields"><label>核对说明<textarea v-model="reviewNote" required /></label><label>核对证据<input v-model="reviewEvidence" required></label></div><div class="actions"><button class="primary">确认本次核对</button><button type="button" @click="review = null">取消</button></div></fieldset></form>
    <form @submit.prevent="loadEntry"><h3>释放暂留／追加调账</h3><div class="actions"><label>原始明细编号<input v-model.number="entryId" type="number" min="1" required></label><button :disabled="busy">查询最新余额</button></div></form>
    <form v-if="entryBalance" @submit.prevent="adjust"><fieldset :disabled="busy" style="border:0;padding:0"><p>明细 #{{ entryBalance.entry.id }} · {{ entryBalance.entry.item_code }} · 最新可调整余额 ¥{{ entryBalance.remaining }}</p><div class="fields"><label>操作<select v-model="adjustment.action"><option v-if="entryBalance.entry.bucket === 'held'" value="release">履约／争议核对后释放暂留</option><option value="adjust">追加归属调整</option></select></label><label>金额<input v-model="adjustment.amount" inputmode="decimal" required></label><label>接收成员<select v-model.number="adjustment.member_id"><option :value="0">未指定</option><option v-for="member in members" :key="member.id" :value="member.id">{{ member.name }}</option></select></label><label v-if="adjustment.action === 'adjust'">目标状态<select v-model="adjustment.bucket"><option value="held">暂留</option><option value="due">应分</option></select></label><label>原因<input v-model="adjustment.note" required></label><label>证据<input v-model="adjustment.evidence" required></label></div><div class="actions"><button class="primary">确认追加记录</button></div></fieldset></form>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api } from '@/utils/api'
import { confirmAction } from '@/shared/ui/confirm'
import { useFrameworkTask } from './useFrameworkTask'
import type { CommercialOrder } from './commercial'
defineProps<{ orders: CommercialOrder[]; members: Array<{ id: number; name: string }>; serviceCodes: Array<{ code: string; label: string }> }>()
const emit = defineEmits<{ changed: [] }>()
const { busy, error, message, run } = useFrameworkTask()
interface Review { id: number; order_id: number; version: number; refunded_total: string; status: string; reason: string }
interface Entry { id: number; amount: string; bucket: string; item_code: string | null; member_id: number | null }
interface EntryBalance { entry: Entry; remaining: string }
const cryptoId = () => crypto.randomUUID()
const delivery = reactive({ order_id: 0, service_code: '', evidence: '', note: '' })
const deliveries = ref<Array<{ service_code: string; version: number }>>([])
const refund = reactive({ order_id: 0, amount: '', reason: '', evidence: '', idempotency_key: cryptoId() })
const reviews = ref<Review[]>([]), review = ref<Review | null>(null), reviewNote = ref(''), reviewEvidence = ref('')
const reductions = ref<Array<{ entry_id: number; expected_remaining: string; amount: string; label: string }>>([])
const entryId = ref(0), entryBalance = ref<EntryBalance | null>(null)
const adjustment = reactive({ action: 'adjust', amount: '', member_id: 0, bucket: 'held', note: '', evidence: '', idempotency_key: cryptoId() })
async function refresh() { reviews.value = await api.get<Review[]>('/api/team-ledger/refund-reviews', {}, { cache: false }) }
async function loadDeliveries() { await run(async () => { deliveries.value = await api.get('/api/team-ledger/service-deliveries', { order_id: delivery.order_id }, { cache: false }) }) }
async function recordDelivery() { await run(async () => { const current = deliveries.value.find(d => d.service_code === delivery.service_code); await api.put(`/api/team-ledger/orders/${delivery.order_id}/service-deliveries/${delivery.service_code}`, { expected_version: current?.version || 0, completed: true, evidence: delivery.evidence, note: delivery.note }); delivery.evidence = ''; deliveries.value = await api.get('/api/team-ledger/service-deliveries', { order_id: delivery.order_id }, { cache: false }); emit('changed') }, '交付职责已记录') }
async function postRefund() { await run(async () => {
  const order = await api.get<CommercialOrder>(`/api/commercial/orders/${refund.order_id}`, {}, { cache: false })
  if (!await confirmAction({ title: '确认实际退款', message: `订单 #${order.id}，本次实际退款 ¥${refund.amount}，此前累计退款 ¥${order.refund_amount}。仅登记，不发起资金操作。` })) return
  await api.post(`/api/team-ledger/orders/${order.id}/partial-refund`, { amount: refund.amount, expected_refunded_total: String(order.refund_amount), reason: refund.reason, evidence: refund.evidence, idempotency_key: refund.idempotency_key }); refund.idempotency_key = cryptoId(); refund.amount = ''; await refresh(); emit('changed')
}) }
async function openReview(item: Review) { await run(async () => { const entries = await api.get<Entry[]>('/api/team-ledger/entries', { order_id: item.order_id, limit: 1000 }, { cache: false }); reductions.value = await Promise.all(entries.filter(e => ['due', 'held'].includes(e.bucket) && Number(e.amount) > 0).map(async e => { const balance = await api.get<EntryBalance>(`/api/team-ledger/entries/${e.id}/balance`, {}, { cache: false }); return { entry_id: e.id, amount: '', expected_remaining: balance.remaining, label: e.item_code || e.bucket } })); review.value = item; reviewNote.value = ''; reviewEvidence.value = '' }) }
async function resolveReview() { await run(async () => { if (!review.value || !await confirmAction({ title: '确认逐项退款核对', message: '将按本页填写的项目追加扣减，未填写项目不自动扣减。确认？' })) return; await api.post(`/api/team-ledger/refund-reviews/${review.value.id}/resolve`, { expected_version: review.value.version, reductions: reductions.value.filter(r => r.amount.trim()).map(({ label: _label, ...row }) => row), note: reviewNote.value, evidence: reviewEvidence.value }); review.value = null; await refresh(); emit('changed') }) }
async function loadEntry() { await run(async () => { entryBalance.value = await api.get<EntryBalance>(`/api/team-ledger/entries/${entryId.value}/balance`, {}, { cache: false }); Object.assign(adjustment, { action: entryBalance.value.entry.bucket === 'held' ? 'release' : 'adjust', amount: '', member_id: 0, note: '', evidence: '', idempotency_key: cryptoId() }) }) }
async function adjust() { await run(async () => { if (!entryBalance.value) return; const body = { amount: adjustment.amount, expected_remaining: entryBalance.value.remaining, evidence: adjustment.evidence, note: adjustment.note, idempotency_key: adjustment.idempotency_key }; if (!await confirmAction({ title: '确认追加台账记录', message: `明细 #${entryBalance.value.entry.id}，调整 ¥${body.amount}。历史记录保留。` })) return; await api.post(`/api/team-ledger/entries/${entryBalance.value.entry.id}/${adjustment.action}`, adjustment.action === 'release' ? { ...body, member_id: adjustment.member_id } : { ...body, target_member_id: adjustment.member_id || null, target_bucket: adjustment.bucket }); entryBalance.value = null; emit('changed') }) }
onMounted(() => run(refresh))
</script>
